def add(code, sub, typ, lv, src, body, opts, ans, exp, passage=None, grp=None, ref=None, core=None, vertical=None):
    d = dict(code=code, sub=sub, type=typ, lv=lv, src=src, body=body, opts=opts, ans=ans, exp=exp)
    for k, v in (('passage', passage), ('grp', grp), ('ref', ref), ('core', core), ('vertical', vertical)):
        if v is not None: d[k] = v
    ITEMS.append(d)


